// Ярость: число использований до долгого отдыха.
func rages(lvl int) int {
	switch {
	case lvl >= 20:
		return 99
	case lvl >= 17:
		return 6
	case lvl >= 12:
		return 5
	case lvl >= 6:
		return 4
	case lvl >= 3:
		return 3
	}
	return 2
}

func attacksFor(class string, lvl int) int {
	switch class {
	case "fighter":
		return 1 + b2i(lvl >= 5) + b2i(lvl >= 11) + b2i(lvl >= 20)
	case "barbarian", "monk", "paladin", "ranger", "bloodhunter":
		return 1 + b2i(lvl >= 5)
	}
	return 1
}
